import { marked } from 'marked';

export interface Book {
	slug: string;
	title: string;
	author: string;
	year: number;
	rating: number;
	tags: string[];
}

const files = import.meta.glob('/content/books/*.md', {
	eager: true,
	query: '?raw',
	import: 'default'
}) as Record<string, string>;

function parse(path: string, raw: string): Book & { body: string } {
	const slug = path.split('/').pop()!.replace(/\.md$/, '');
	const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
	const data: Record<string, string> = {};
	for (const line of (m?.[1] ?? '').split(/\r?\n/)) {
		const i = line.indexOf(':');
		if (i > 0) data[line.slice(0, i).trim()] = line.slice(i + 1).trim();
	}
	const unquote = (s: string) => s.trim().replace(/^(["'])(.*)\1$/, '$2');
	const tags = (data.tags ?? '')
		.replace(/^\[|\]$/g, '')
		.split(',')
		.map(unquote)
		.filter(Boolean);
	return {
		slug,
		title: unquote(data.title ?? slug),
		author: unquote(data.author ?? ''),
		year: Number(data.year),
		rating: Number(data.rating),
		tags,
		body: m?.[2] ?? raw
	};
}

const all = Object.entries(files).map(([p, r]) => parse(p, r));
const byTitle = (a: Book, b: Book) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0);

function strip({ body, ...book }: Book & { body: string }): Book {
	return book;
}

export function listBooks(): Book[] {
	return all.map(strip).sort(byTitle);
}

export function topRated(n: number): Book[] {
	return listBooks()
		.sort((a, b) => b.rating - a.rating || byTitle(a, b))
		.slice(0, n);
}

export function getBook(slug: string) {
	const b = all.find((x) => x.slug === slug);
	if (!b) return undefined;
	return { ...strip(b), html: marked.parse(b.body, { async: false }) as string };
}
